INSERT INTO `recursos` (`id`, `titulo`, `descricao`, `tipo`, `tema`, `imageUrl`, `downloadUrl`, `isPremium`, `isNovo`, `publicado`, `createdAt`, `updatedAt`) VALUES (1,'Gestão de Saúde Mental no Local de Trabalho','Como transformar desafios em oportunidades de crescimento organizacional. Implementação de políticas de saúde mental eficazes.','ebook','Saúde Mental','https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(2,'ROI do Bem-Estar: Impacto nos Resultados','Dados concretos sobre retorno do investimento em bem-estar. Aumente a produtividade e reduza o absentismo.','ebook','ROI','https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(3,'10 Sinais de Burnout na Sua Equipa','Guia prático para identificar e resolver problemas de stress no trabalho. Dicas para gestores prevenirem o burnout.','ebook','Burnout','https://images.unsplash.com/photo-1541199249251-f713e6145474?w=600&q=80',NULL,0,1,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(4,'Employee Assistance Programs (EAP): O Futuro do RH','Tudo o que precisa saber para implementar com sucesso. Benefícios e casos de uso do EAP.','ebook','EAP','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(5,'O Guia Completo para Reduzir o Turnover','Estratégias para manter os melhores talentos na sua organização. Insights práticos para melhorar a retenção.','ebook','Retenção','https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(6,'Liderança Empática: O Novo Paradigma','Como desenvolver competências de liderança que promovem o bem-estar e a performance das equipas.','ebook','Liderança','https://images.unsplash.com/photo-1552664730-d307ca884978?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(7,'Avaliação de Risco de Burnout','Questionário baseado na Escala de Maslach para avaliar o nível de burnout da sua equipa.','ferramenta','Burnout','https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=600&q=80',NULL,0,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(8,'Scorecard de Bem-Estar Organizacional','Avalie o estado atual do bem-estar na sua empresa com este diagnóstico completo.','ferramenta','Diagnóstico','https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=600&q=80',NULL,0,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(9,'Calculadora de ROI do EAP','Calcule o retorno do investimento de um programa de assistência ao colaborador.','ferramenta','ROI','https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?w=600&q=80',NULL,0,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(10,'Avaliação de Clima Organizacional','Meça a satisfação e engagement dos colaboradores com este questionário validado.','ferramenta','Clima','https://images.unsplash.com/photo-1600880292203-757bb62b4baf?w=600&q=80',NULL,0,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(11,'Como Implementar um EAP de Sucesso','Webinar com Ana Ruivo sobre as melhores práticas de implementação de programas de assistência.','webinar','EAP','https://images.unsplash.com/photo-1587825140708-dfaf72ae4b04?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(12,'Prevenção de Burnout: Estratégias Práticas','Aprenda a identificar e prevenir o burnout nas suas equipas com técnicas comprovadas.','webinar','Burnout','https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=600&q=80',NULL,0,1,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(13,'O Papel do RH na Saúde Mental','Como os profissionais de RH podem liderar a transformação do bem-estar corporativo.','webinar','RH','https://images.unsplash.com/photo-1542744173-8e7e53415bb0?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(14,'Literacia Financeira: Reduzir o Stress dos Colaboradores','Como programas de educação financeira impactam o bem-estar e a produtividade.','webinar','Finanças','https://images.unsplash.com/photo-1579621970563-ebec7560ff3e?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(15,'5 Tendências de Bem-Estar Corporativo para 2025','As principais tendências que vão moldar o futuro do trabalho e do bem-estar nas empresas.','artigo','Tendências','https://images.unsplash.com/photo-1497366216548-37526070297c?w=600&q=80',NULL,0,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(16,'Como Medir o Impacto de um Programa de Bem-Estar','Métricas e KPIs essenciais para avaliar o sucesso das suas iniciativas de bem-estar.','artigo','ROI','https://images.unsplash.com/photo-1504868584819-f8e8b4b6d7e3?w=600&q=80',NULL,0,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(17,'A Importância do Apoio Psicológico no Trabalho','Porque é que o acesso a psicólogos é fundamental para a saúde das organizações.','artigo','Saúde Mental','https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=600&q=80',NULL,0,1,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(18,'Trabalho Remoto e Saúde Mental: Desafios e Soluções','Como manter o bem-estar das equipas em modelos de trabalho híbrido e remoto.','artigo','Trabalho Remoto','https://images.unsplash.com/photo-1593642632559-0c6d3fc62b89?w=600&q=80',NULL,0,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(19,'Checklist de Implementação de EAP','Lista completa de passos para implementar um programa de assistência ao colaborador.','guia','EAP','https://images.unsplash.com/photo-1484480974693-6ca0a78fb36b?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(20,'Auditoria de Bem-Estar Organizacional','20 pontos essenciais para avaliar o estado do bem-estar na sua empresa.','guia','Diagnóstico','https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(21,'Plano de Comunicação Interna de Bem-Estar','Template para comunicar eficazmente as iniciativas de bem-estar aos colaboradores.','template','Comunicação','https://images.unsplash.com/photo-1557804506-669a67965ba0?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(22,'O Custo do Absentismo em Portugal','Dados e estatísticas sobre o impacto económico do absentismo nas empresas portuguesas.','guia','Absentismo','https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:47','2026-06-30 17:24:47'),(23,'Burnout em Números: A Realidade Portuguesa','Estatísticas alarmantes sobre o burnout em Portugal e o seu impacto nas organizações.','guia','Burnout','https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?w=600&q=80',NULL,0,1,1,'2026-06-30 17:24:48','2026-06-30 17:24:48'),(24,'Anatomia de um EAP de Sucesso','Os componentes essenciais de um programa de assistência ao colaborador eficaz.','guia','EAP','https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:48','2026-06-30 17:24:48'),(25,'Ep. 1: O Futuro do Trabalho e o Bem-Estar','Conversa com especialistas sobre as tendências que vão moldar o futuro do trabalho.','artigo','Tendências','https://images.unsplash.com/photo-1478737270239-2f02b77fc618?w=600&q=80',NULL,0,0,1,'2026-06-30 17:24:48','2026-06-30 17:24:48'),(26,'Ep. 2: Liderança e Saúde Mental','Como os líderes podem promover ambientes de trabalho saudáveis e produtivos.','artigo','Liderança','https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=600&q=80',NULL,0,0,1,'2026-06-30 17:24:48','2026-06-30 17:24:48'),(27,'Ep. 3: Casos de Sucesso em EAP','Histórias reais de empresas que transformaram a sua cultura com programas de bem-estar.','artigo','EAP','https://images.unsplash.com/photo-1590602847861-f357a9332bbc?w=600&q=80',NULL,0,1,1,'2026-06-30 17:24:48','2026-06-30 17:24:48'),(28,'RTP: Transformação Cultural com EAP','Como a RTP reduziu o absentismo em 32% com o programa TEAM 24.','artigo','Media','https://images.unsplash.com/photo-1504711434969-e33886168f5c?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:48','2026-06-30 17:24:48'),(29,'Salvador Caetano: Bem-Estar na Indústria','Implementação de um programa de saúde mental em ambiente industrial.','artigo','Indústria','https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:48','2026-06-30 17:24:48'),(30,'Adecco: EAP para Equipas Distribuídas','Estratégias para implementar bem-estar em equipas geograficamente dispersas.','artigo','RH','https://images.unsplash.com/photo-1600880292203-757bb62b4baf?w=600&q=80',NULL,1,0,1,'2026-06-30 17:24:48','2026-06-30 17:24:48');
