INSERT INTO `casos` (`id`, `empresa`, `setor`, `logoUrl`, `imagemUrl`, `resultado`, `descricao`, `citacao`, `citacaoAutor`, `citacaoRole`, `metrica1Label`, `metrica1Valor`, `metrica2Label`, `metrica2Valor`, `metrica3Label`, `metrica3Valor`, `destaque`, `publicado`, `createdAt`, `updatedAt`) VALUES (30001,'ADECCO','Recrutamento','/media/5C_QbPIzdT_6dfc4aa3.png','/media/hV1TLeRsGr_6903b021.webp','','A TEAM 24 tornou possível uma das prioridades da política de recursos humanos da Adecco: a promoção da saúde mental.','O MAIOR IMPACTO QUE VERIFICÁMOS PRENDE-SE COM O FACTO DE SABERMOS QUE TEMOS COLABORADORES A SEREM ACOMPANHADOS E QUE, SE A EMPRESA NÃO PROPORCIONASSE ESTE SERVIÇO, PROVAVELMENTE ESTARIAM SEM SUPORTE','VÂNIA BORGES','Diretora de recursos humanos','','','','','','',0,1,'2026-03-09 15:48:23','2026-08-20 11:28:25'),(60002,'SPORTING CLUBE DE PORTUGAL','Desporto','/media/ChJkVN9teu_177ffc32.png','/media/A3LW-TEIva_ca9405ac.webp','','A parceria com o Sporting CP disponibiliza apoio psicológico a mais de 600 colaboradores.','A PARCERIA COM A TEAM 24 VISA CRIAR AWARENESS NA ORGANIZAÇÃO PARA UM TEMA QUE AINDA TENDE A SER ALGO ESTIGMATIZADO NA NOSSA SOCIEDADE','HENRIQUE DIAS DUARTE','DRH DO SPORTING CLUBE DE PORTUGAL','','','','','','',0,1,'2026-03-23 11:53:38','2026-08-20 11:28:25'),(60003,'ACT','Público','/media/Z2gGLGtm2h_c84915fa.png','/media/XddHtbrGtT_377525ed.webp','','A ACT implementou apoio psicológico online para reduzir stress e burnout nos colaboradores.','Com a disponibilização de um serviço de psicologia online, contamos contribuir para aumentar o bem-estar dos trabalhadores da ACT','Daniel Alves','Chefe de Divisão de Formação e Recurso Humanos da ACT','','','','','','',0,1,'2026-03-23 12:02:48','2026-08-20 11:28:25'),(60004,'DOUTOR FINANÇAS','Financeiro','/media/EMOKiCGZp1_334eb5ae.png','/media/iv8ZmpqLd2_e20eb740.webp','','O Doutor Finanças posiciona a saúde mental como eixo estratégico na gestão de pessoas.','A SAÚDE MENTAL DEVE SER LEVADA MUITO A SÉRIO, É TÃO OU MAIS IMPORTANTE QUE A SAÚDE FÍSICA','RUI BAIRRADA','CEO DO DOUTOR FINANÇAS','','','','','','',0,0,'2026-03-23 12:05:50','2026-08-20 11:28:25'),(60005,'SALVADOR CAETANO','Automóvel','/media/4ZfuX8U7Aj_63fb4c0b.png','/media/fwlDMez3EX_a893d415.webp','','A Salvador Caetano garantiu o bem-estar dos colaboradores no pós-pandemia com apoio psicológico.','A TEAM 24 AJUDOU-NOS A GARANTIR QUE OS NOSSOS COLABORADORES TÊM ACESSO AO APOIO DE QUE NECESSITAM','RESPONSÁVEL DE RH','Salvador Caetano','','','','','','',0,1,'2026-03-23 12:10:00','2026-08-20 11:28:25');
