INSERT INTO `carreiras` (`id`, `titulo`, `slug`, `departamento`, `localizacao`, `tipo`, `nivel`, `descricao`, `requisitos`, `beneficios`, `salarioMin`, `salarioMax`, `ativo`, `publicado`, `createdAt`, `updatedAt`) VALUES (1,'Psicólogo(a) Organizacional','psicologo-organizacional','Psicologia Organizacional','Online, com deslocações pontuais a clientes','full-time','medio','A TEAM24 é uma empresa especializada em Employee Assistance Program – EAP e saúde mental empresarial. Trabalhamos com organizações que querem cuidar melhor das suas pessoas, oferecendo apoio psicológico, jurídico, financeiro e nutricional aos seus colaboradores, de forma digital, confidencial e acessível.\n\nEstamos a recrutar um/a Consultor/a de Psicologia Organizacional para assumir um papel estratégico na relação com os nossos clientes empresariais.\n\nEste não é um cargo clínico. Procuramos alguém com visão consultiva, capacidade de comunicação com decisores de Recursos Humanos e interesse em transformar dados, necessidades organizacionais e indicadores de utilização em recomendações práticas para as empresas.','Licenciatura ou Mestrado em Psicologia (preferencialmente com especialização em Psicologia Organizacional ou do Trabalho);\nExperiência mínima de 2 anos em contexto organizacional ou de consultoria;\nCapacidade de análise e interpretação de dados de utilização;\nExcelente comunicação verbal e escrita;\nOrientação para o cliente e capacidade de gestão de relações.','Trabalho remoto com flexibilidade;\nIntegração numa empresa em crescimento;\nFormação contínua;\nParticipação ativa na estratégia da empresa.',NULL,NULL,0,0,'2026-03-05 17:49:45','2026-06-30 20:40:32'),(30001,'Assistente Social — Programa de Apoio ao Colaborador (EAP)','assistente-social-programa-de-apoio-ao-colaborador-eap','Serviço Social','Online','full-time','medio','A TEAM24 é uma empresa especializada em Employee Assistance Program – EAP e bem-estar organizacional.\nTrabalhamos com organizações que querem cuidar melhor das suas pessoas, oferecendo apoio psicológico, social, jurídico, financeiro e nutricional aos seus colaboradores, de forma digital, confidencial e acessível.\nEstamos a recrutar um/a Assistente Social para integrar a nossa equipa de apoio direto ao colaborador.\nEste é um papel de proximidade e acompanhamento — a ponte entre a pessoa e as respostas de que precisa, para que possa manter o equilíbrio entre a vida profissional e pessoal sem deixar o trabalho para trás.\n \nPrincipais responsabilidades\nPrestar apoio social aos colaboradores das empresas-cliente TEAM24, por via digital (chat, voz ou vídeo)\nAjudar os colaboradores a encontrar e aceder a recursos e serviços de que necessitam — apoios públicos, subsídios e legalizações; apoio a dependentes (crianças, idosos); apoio doméstico; apoio na maternidade/parentalidade — e articular com entidades públicas/do Estado sempre que necessário\nGerir e manter atualizada a rede de parceiros e entidades externas do EAP, e garantir estas respostas em condições favoráveis\nFazer a ponte entre o colaborador, a TEAM24 e os parceiros externos, assegurando encaminhamentos rápidos e adequados\nGerir o trabalho administrativo do serviço — marcação e gestão de consultas, atendimento telefónico e por chat\nAcompanhar casos ao longo do tempo, com registo rigoroso e confidencial','Formação superior em Serviço Social\nInscrição válida na Ordem dos Assistentes Sociais\nExperiência prévia em acompanhamento social, apoio ao colaborador ou funções semelhantes\nConhecimento da rede social e de recursos de apoio\nEscuta ativa, empatia e capacidade de gerir situações delicadas com sensibilidade\nConforto com trabalho digital (app, videochamada, plataformas internas)\nDomínio do português e inglês','Integração numa empresa inovadora na área da saúde mental empresarial\nTrabalho com impacto direto e visível na vida das pessoas\nEquipa multidisciplinar de apoio (psicólogos, jurídicos, financeiros)\nModelo híbrido/online, com deslocações pontuais a clientes\nRemuneração competitiva, ajustada à experiência demonstrada\n ',NULL,NULL,1,1,'2026-07-09 13:32:27','2026-07-09 13:32:27'),(30002,'Comercial B2B | Saúde Mental Empresarial','comercial-b2b-saude-mental-empresarial','Comercial','Porto / Modelo híbrido, com deslocações a clientes','full-time','medio','Estamos a recrutar um/a Comercial B2B para apresentar os serviços da TEAM24 a potenciais clientes empresariais e gerir a relação comercial com a nossa carteira de clientes.','Experiência comercial em contexto B2B; Experiência na venda de serviços a empresas, preferencialmente junto de Recursos Humanos.','Integração numa empresa inovadora na área da saúde mental empresarial; Remuneração competitiva, com componente fixa e variável.',NULL,NULL,0,0,'2026-05-24 20:04:48','2026-06-21 12:18:16'),(30003,'Psicóloga(o) Clínica(o) Sénior | Coordenação Clínica','psicologa-clinica-senior-coordenacao-clinica','Clínica','Online, com possibilidade de trabalho e reuniões presenciais sempre que necessário','full-time','medio','Estamos a recrutar uma Psicóloga Clínica Sénior para assumir a coordenação da rede de psicólogos clínicos da TEAM24, garantindo a qualidade, consistência e segurança dos serviços de psicologia prestados aos colaboradores das empresas clientes.','Formação superior em Psicologia Clínica; Cédula profissional válida da Ordem dos Psicólogos Portugueses — obrigatório; Experiência clínica sólida, preferencialmente igual ou superior a 8 anos.','Integração numa empresa inovadora na área da saúde mental empresarial; Função estratégica na estrutura clínica da TEAM24.',NULL,NULL,0,0,'2026-05-24 20:04:48','2026-06-21 12:18:27'),(30004,'Psicólogo/a Clínico/a | Prestação de Serviços','psicologo-clinico-prestacao-servicos','Clínica','Modelo online','freelance','medio','Estamos a reforçar a nossa rede de Psicólogos/as Clínicos/as para prestação de consultas de psicologia aos colaboradores das empresas nossas clientes. Trata-se de uma colaboração em regime de prestação de serviços, com flexibilidade na definição de horários e disponibilidades.','Formação superior em Psicologia Clínica; Cédula profissional válida da Ordem dos Psicólogos Portugueses — obrigatório; Experiência em acompanhamento psicológico de adultos.','Regime de prestação de serviços; Flexibilidade na definição de horários; Integração numa rede clínica especializada em saúde mental empresarial.',NULL,NULL,1,1,'2026-05-24 20:04:48','2026-05-26 09:27:39'),(60003,'Full Stack Developer (AI-Driven Development Environment)','developer-mid-level','IT','Remote','full-time','medio','A TEAM24 está à procura de um Developer Mid-Level para integrar a nossa equipa de desenvolvimento e participar na criação de soluções digitais web, robustas, escaláveis e orientadas para a qualidade.','Formação em Engenharia Informática ou área similar; Experiência entre 3 a 5 anos em desenvolvimento de software; Experiência prática com React e Node.js.','Integração numa equipa dinâmica, colaborativa e focada em inovação; Participação em projetos digitais com impacto real.',NULL,NULL,1,0,'2026-06-07 09:42:12','2026-07-10 10:28:56'),(60004,'Psicólogo(a) — Apoio Psicológico 24/7','psicologoa-apoio-psicologico-247','Clinica','25h/semana · Período noturno e fins de semana · Remoto','part-time','medio','Somos uma empresa portuguesa dedicada à saúde mental e ao bem-estar psicológico no contexto corporativo. Através da nossa app, damos a colaboradores de empresas de referência, como o Sporting CP, acesso a apoio psicológico confidencial, imediato e disponível 24 horas por dia, 7 dias por semana.\n\nA nossa missão é simples: democratizar o acesso à saúde mental no mundo do trabalho. Para garantir que ninguém fica sem resposta a qualquer hora, estamos a reforçar a equipa clínica para o período noturno e de fim de semana.\n\nProcuramos um(a) psicólogo(a) para integrar a nossa equipa em horário noturno e de fim de semana, combinando atendimento direto com produção de conteúdo e análise técnica. As principais responsabilidades são:\n\nAtendimento da linha de Chat e Voz, acompanhar e apoiar os utilizadores da app de forma empática, confidencial e segura, incluindo a gestão de situações de maior urgência de acordo com os nossos protocolos.\nCriação e revisão de conteúdos de psicologia, desenvolver e rever materiais para formações, artigos, e-books e recursos de autocuidado.\nAnálises e relatórios de avaliação, elaborar análises e relatórios a partir do COPSOQ e de outros instrumentos de avaliação psicossocial (ex.: GAD-7, PHQ-9), traduzindo os dados em recomendações úteis para as organizações.\n\n25 horas por semana, em regime part-time.\nTurnos em período noturno e ao fim de semana, organizados em escala rotativa e previsível.\nTrabalho 100% remoto.','Licenciatura e Mestrado em Psicologia.\nInscrição na Ordem dos Psicólogos Portugueses (OPP) com cédula profissional válida — requisito obrigatório.\nExperiência em apoio psicológico, aconselhamento ou intervenção em crise.\nBoa capacidade de escrita e à-vontade na produção de conteúdos.\nConhecimento de instrumentos de avaliação psicológica e psicossocial (o COPSOQ é uma mais-valia).\nConforto com ferramentas digitais e atendimento remoto.\nDisponibilidade real para trabalhar à noite e ao fim de semana.\n\nValorizamos ainda\nExperiência prévia em EAP (Employee Assistance Programs) ou saúde ocupacional.\nFormação ou interesse em psicologia organizacional.\nDomínio de inglês e/ou espanhol (estamos a expandir para Espanha).','Contrato part-time com suplemento de trabalho noturno.\nTrabalho 100% remoto, com escala estável e equilibrada.\nIntegração numa equipa clínica com supervisão e formação contínua.\nUm projeto com propósito, a crescer em Portugal e Espanha.\nRemuneração de acordo com a experiência.',NULL,NULL,1,0,'2026-06-07 09:47:16','2026-07-10 10:28:53');
