INSERT INTO `imprensa` (`id`, `titulo`, `publicacao`, `tipo`, `resumo`, `url`, `imagemUrl`, `dataPublicacao`, `destaque`, `publicado`, `createdAt`, `updatedAt`) VALUES (1,'A NOSSA MISSÃO É LEVAR A SAÚDE MENTAL AO MAIOR NÚMERO DE PESSOAS POSSÍVEL','Corporate Wellness','artigo','O bem-estar psicológico é um forte contributo para melhorar o desempenho profissional. A responsável principal pela Team 24 elenca os bons efeitos desta correlação e a forma como, nas organizações que contratam os seus serviços, a empresa desenvolve o \"Plano de Apoio Psicológico\", o instrumento por excelência de promoção da saúde mental.','https://team24.pt/wp-content/uploads/2022/05/Team24_Entrevista.pdf',NULL,NULL,0,1,'2026-03-09 12:31:16','2026-03-09 14:12:16');
